// main.js - puts it all together

const isSmallScreen = window.innerWidth < 900;
let gameScene = null;

class OutpostScene extends Phaser.Scene {
  constructor() {
      super("Outpost");
        }

          create() {
              buildWorld(this);
                  this.player = createPlayer(this);
                      this.solids.forEach(s => this.physics.add.collider(this.player, s));

                          this.keys = this.input.keyboard.addKeys({
                                up: "W", down: "S", left: "A", right: "D",
                                      up2: "UP", down2: "DOWN", left2: "LEFT", right2: "RIGHT",
                                            interact: "E", space: "SPACE"
                                                });

                                                    setupMobileControls(() => this.interact());

                                                        // on phones the canvas fills the screen and the camera follows the astronaut
                                                            if (isSmallScreen) {
                                                                  this.cameras.main.setBounds(0, 0, 960, 640);
                                                                        this.cameras.main.startFollow(this.player, true, 0.1, 0.1);
                                                                            }

                                                                                this.input.keyboard.on("keydown-M", () => openMap());

                                                                                    // tap or click anywhere to walk there (tap a building to walk there and use it)
                                                                                        this.target = null;
                                                                                            this.input.on("pointerdown", p => tapTo(this, p.worldX, p.worldY));

                                                                                                gameScene = this;
                                                                                                    loadSpaceWeather();
                                                                                                        state.paused = true;
                                                                                                            showStart();
                                                                                                              }

                                                                                                                update() {
                                                                                                                    if (state.over || state.paused) {
                                                                                                                          this.target = null;
                                                                                                                                stopPlayer(this);
                                                                                                                                      return;
                                                                                                                                          }
                                                                                                                                              movePlayer(this);

                                                                                                                                                  if (Phaser.Input.Keyboard.JustDown(this.keys.interact) ||
                                                                                                                                                          Phaser.Input.Keyboard.JustDown(this.keys.space)) {
                                                                                                                                                                this.interact();
                                                                                                                                                                    }

                                                                                                                                                                        refreshNearby(this);
                                                                                                                                                                          }

                                                                                                                                                                            interact() {
                                                                                                                                                                                if (state.over || state.paused) return;
                                                                                                                                                                                    const b = nearestBuilding(this.player);
                                                                                                                                                                                        if (!b) {
                                                                                                                                                                                              showBanner("Move closer to a building first", false);
                                                                                                                                                                                                    return;
                                                                                                                                                                                                        }
                                                                                                                                                                                                            useBuilding(b);
                                                                                                                                                                                                              }
                                                                                                                                                                                                              }

                                                                                                                                                                                                              function tapTo(scene, x, y) {
                                                                                                                                                                                                                if (state.paused || state.over) return;

                                                                                                                                                                                                                  // locked (dark) areas
                                                                                                                                                                                                                    for (const name in scene.fogs) {
                                                                                                                                                                                                                        if (scene.fogs[name].rect.getBounds().contains(x, y)) {
                                                                                                                                                                                                                              showBanner("Locked! Finish the stage to open this area.", false);
                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                            const b = BUILDINGS.find(b => Math.abs(x - b.x) < 62 && Math.abs(y - b.y) < 46);
                                                                                                                                                                                                                                              if (b) walkTo(scene, b.x, b.y + 78, b);
                                                                                                                                                                                                                                                else walkTo(scene, x, y, null);
                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                // walk to a spot (building is only used to say "Arrived at..."; it is never used automatically)
                                                                                                                                                                                                                                                function walkTo(scene, x, y, building) {
                                                                                                                                                                                                                                                  scene.target = { x: x, y: y, building: building, lastDist: Infinity, checked: scene.time.now };

                                                                                                                                                                                                                                                    // a ring where you tapped
                                                                                                                                                                                                                                                      const ring = scene.add.circle(x, y, 12, 0xffffff, 0.5).setDepth(5);
                                                                                                                                                                                                                                                        scene.tweens.add({ targets: ring, scale: 2, alpha: 0, duration: 600, onComplete: () => ring.destroy() });
                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                        // ---------- map ----------
                                                                                                                                                                                                                                                        function mapSvg(scene) {
                                                                                                                                                                                                                                                          let s = '<svg viewBox="0 0 960 640" role="img" aria-label="Map of the base">' +
                                                                                                                                                                                                                                                              '<rect width="960" height="640" fill="' + siteColour() + '"/>' +
                                                                                                                                                                                                                                                                  '<g stroke="#9ca4b2" stroke-width="35" opacity="0.7">' +
                                                                                                                                                                                                                                                                      '<line x1="480" y1="220" x2="480" y2="410"/><line x1="170" y1="220" x2="790" y2="220"/><line x1="260" y1="410" x2="700" y2="410"/></g>' +
                                                                                                                                                                                                                                                                          '<circle cx="480" cy="320" r="70" fill="none" stroke="#e1d5a4" stroke-width="4"/>';

                                                                                                                                                                                                                                                                            BUILDINGS.forEach((b, n) => {
                                                                                                                                                                                                                                                                                const locked = b.stage > state.stage;
                                                                                                                                                                                                                                                                                    const colour = "#" + b.colour.toString(16).padStart(6, "0");
                                                                                                                                                                                                                                                                                        s += '<g' + (locked ? '' : ' data-b="' + b.name + '" style="cursor:pointer"') + '>' +
                                                                                                                                                                                                                                                                                              '<rect x="' + (b.x - 56) + '" y="' + (b.y - 38) + '" width="112" height="76" rx="8" fill="' + (locked ? "#1b2236" : colour) + '" stroke="#fff" stroke-width="4"/>' +
                                                                                                                                                                                                                                                                                                    '<text x="' + b.x + '" y="' + (b.y + 14) + '" font-size="44" font-weight="bold" text-anchor="middle" fill="' + (locked ? "#6b7799" : "#fff") + '">' + (n + 1) + '</text>' +
                                                                                                                                                                                                                                                                                                          '<text x="' + b.x + '" y="' + (b.y + 70) + '" font-size="26" text-anchor="middle" fill="' + (locked ? "#c4cbe0" : "#fff") + '" stroke="#101827" stroke-width="5" paint-order="stroke">' + b.name + '</text></g>';
                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                              // where the astronaut is right now
                                                                                                                                                                                                                                                                                                                const px = Math.round(scene.player.x), py = Math.round(scene.player.y);
                                                                                                                                                                                                                                                                                                                  s += '<circle cx="' + px + '" cy="' + py + '" r="16" fill="#ffd77a" stroke="#101827" stroke-width="4"/>' +
                                                                                                                                                                                                                                                                                                                      '<text x="' + px + '" y="' + (py - 24) + '" font-size="26" font-weight="bold" text-anchor="middle" fill="#ffd77a" stroke="#101827" stroke-width="5" paint-order="stroke">YOU</text></svg>';

                                                                                                                                                                                                                                                                                                                        BUILDINGS.forEach((b, n) => {
                                                                                                                                                                                                                                                                                                                            if (b.stage > state.stage) {
                                                                                                                                                                                                                                                                                                                                  s += '<div class="legend-row locked"><b>' + (n + 1) + '</b>' + b.name + ': locked until Stage ' + b.stage + ' is finished</div>';
                                                                                                                                                                                                                                                                                                                                      } else {
                                                                                                                                                                                                                                                                                                                                            s += '<div class="legend-row"><b>' + (n + 1) + '</b>' + b.name + ': ' + b.job + ' (' + b.cost + ' power)</div>';
                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                    return s;
                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                    // shows the whole base. Tapping a building on the map walks there, it doesn't use it.
                                                                                                                                                                                                                                                                                                                                                    function showMap(scene, onClose) {
                                                                                                                                                                                                                                                                                                                                                      state.paused = true;
                                                                                                                                                                                                                                                                                                                                                        showOverlay("Base map", "Tap a building to walk there. You still press USE yourself.", "", [
                                                                                                                                                                                                                                                                                                                                                            { label: "Close map", note: "", onClick: () => { hideOverlay(); onClose(); } }
                                                                                                                                                                                                                                                                                                                                                              ]);
                                                                                                                                                                                                                                                                                                                                                                const extra = document.getElementById("ov-extra");
                                                                                                                                                                                                                                                                                                                                                                  extra.innerHTML = mapSvg(scene);
                                                                                                                                                                                                                                                                                                                                                                    extra.querySelectorAll("[data-b]").forEach(el => {
                                                                                                                                                                                                                                                                                                                                                                        el.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                              const b = BUILDINGS.find(x => x.name === el.dataset.b);
                                                                                                                                                                                                                                                                                                                                                                                    hideOverlay();
                                                                                                                                                                                                                                                                                                                                                                                          state.paused = false;
                                                                                                                                                                                                                                                                                                                                                                                                walkTo(scene, b.x, b.y + 78, b);
                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                      function openMap() {
                                                                                                                                                                                                                                                                                                                                                                                                        if (state.paused || state.over || !gameScene) return;
                                                                                                                                                                                                                                                                                                                                                                                                          showMap(gameScene, () => { state.paused = false; });
                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                          // highlight the nearest building, tell the player what it does, and relabel the button
                                                                                                                                                                                                                                                                                                                                                                                                          function refreshNearby(scene) {
                                                                                                                                                                                                                                                                                                                                                                                                            const near = nearestBuilding(scene.player);
                                                                                                                                                                                                                                                                                                                                                                                                              showNearby(scene, near);
                                                                                                                                                                                                                                                                                                                                                                                                                hint(near
                                                                                                                                                                                                                                                                                                                                                                                                                    ? "NEAR " + near.name + ": " + near.job + " (" + near.cost + " power)"
                                                                                                                                                                                                                                                                                                                                                                                                                        : "Walk to a building, or tap one to go there.");

                                                                                                                                                                                                                                                                                                                                                                                                                          const label = near ? "USE<br>" + near.name : "INTERACT";
                                                                                                                                                                                                                                                                                                                                                                                                                            if (scene.lastLabel !== label) {
                                                                                                                                                                                                                                                                                                                                                                                                                                const btn = document.getElementById("interact");
                                                                                                                                                                                                                                                                                                                                                                                                                                    btn.innerHTML = label;
                                                                                                                                                                                                                                                                                                                                                                                                                                        btn.className = near ? "ready" : "";
                                                                                                                                                                                                                                                                                                                                                                                                                                            scene.lastLabel = label;
                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                              // the long help text is tucked into a "More help" section so the start screen stays short
                                                                                                                                                                                                                                                                                                                                                                                                                                              function addMoreHelp(extra) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                const more = document.createElement("details");
                                                                                                                                                                                                                                                                                                                                                                                                                                                  more.className = "more";
                                                                                                                                                                                                                                                                                                                                                                                                                                                    const summary = document.createElement("summary");
                                                                                                                                                                                                                                                                                                                                                                                                                                                      summary.textContent = "More help and data sources";
                                                                                                                                                                                                                                                                                                                                                                                                                                                        const body = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                          body.className = "fullhelp";
                                                                                                                                                                                                                                                                                                                                                                                                                                                            body.textContent = HELP_TEXT;
                                                                                                                                                                                                                                                                                                                                                                                                                                                              more.appendChild(summary);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                more.appendChild(body);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  extra.appendChild(more);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const DIFFICULTY_NOTES = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    easy: "More power, fewer events, gentler storms.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      normal: "A balanced mission.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        hard: "Less power, more events, stronger storms."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function showStart() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const saved = loadProgress();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            state.difficulty = loadDifficulty();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const begin = index => () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  hideOverlay();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      startStage(index, false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          showMap(gameScene, startDay);   // quick look at the base before day 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const buttons = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (saved > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    buttons.push({ label: "Continue at Stage " + (saved + 1), note: "Your progress was saved in this browser.", onClick: begin(saved) });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        buttons.push({ label: "New game", note: "Start again from Stage 1.", onClick: () => { clearProgress(); begin(0)(); } });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              buttons.push({ label: "Start mission", note: "", onClick: begin(0) });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  showOverlay("Outpost Zero", HELP_SHORT, "", buttons);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // difficulty is right under the short intro, so nobody misses it
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const extra = document.getElementById("ov-extra");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        extra.innerHTML = '<p><b>Choose a difficulty</b></p><div class="diff"></div><p class="diff-note"></p>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const row = extra.querySelector(".diff");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const note = extra.querySelector(".diff-note");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              note.textContent = DIFFICULTY_NOTES[state.difficulty];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Object.keys(DIFFICULTY).forEach(key => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const btn = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        btn.textContent = DIFFICULTY[key].label;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            btn.className = key === state.difficulty ? "on" : "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                btn.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      state.difficulty = key;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            saveDifficulty(key);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  row.querySelectorAll("button").forEach(x => { x.className = ""; });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        btn.className = "on";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              note.textContent = DIFFICULTY_NOTES[key];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      row.appendChild(btn);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          addMoreHelp(extra);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function showHelp() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            showOverlay("How to play", HELP_SHORT, "", [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                { label: "Back to game", note: "", onClick: () => { hideOverlay(); state.paused = false; } }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    addMoreHelp(document.getElementById("ov-extra"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // set up a stage: refill supplies, open the new area
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function startStage(index, animate) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      state.stage = index;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        state.day = 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          state.streak = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            state.maxPower = Math.max(4, STAGES[index].power + DIFFICULTY[state.difficulty].power);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // a supply ship tops things up, but never lowers them
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                state.air = Math.max(state.air, 70);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  state.food = Math.max(state.food, 70);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    state.shield = Math.max(state.shield, 70);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      state.health = Math.max(state.health, 80);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (index >= 2) state.science = 0;   // the last stages count their own science
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          state.damage = { radiation: 0, air: 0, food: 0, storm: 0 };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            pendingAdvice = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              gameScene.cameras.main.setBackgroundColor(siteColour());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                saveProgress(index);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  applyUnlocks(gameScene, animate);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function startDay() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    state.paused = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      state.power = state.maxPower;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        dayStart = { science: state.science, health: state.health };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          updateDashboard();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let text = dayWord() + " " + state.day + " begins. Goal: " + STAGES[state.stage].goal;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (pendingAdvice) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  pendingAdvice = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      text = "Earth's reply from yesterday finally arrived: " + earthAdvice();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          showBanner("Earth's reply arrived!", true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              playSound("radio");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  message(text);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const ev = pickEvent();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!ev) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        state.paused = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          playSound("alert");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const choose = (option, isShelter) => () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const result = applyEffects(optionFx(option));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (isShelter) state.stats.sheltered++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        hideOverlay();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            state.paused = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                updateDashboard();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // storms shake the screen (unless the player asked their device for less motion)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const calm = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (optionFx(option).storm && !calm) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  gameScene.cameras.main.shake(350, 0.01);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        gameScene.cameras.main.flash(250, 255, 80, 80);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                showBanner(option.label, true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    message(option.label + ". " + result);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (state.health <= 0) failStage(true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            showOverlay(ev.title, ev.text, ev.source, [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                { label: ev.a.label, note: optionNote(ev.a), onClick: choose(ev.a, ev.title === "Big solar flare") },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    { label: ev.b.label, note: optionNote(ev.b), onClick: choose(ev.b, false) }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function finishDay() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (state.over || state.paused) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const st = STAGES[state.stage];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const report = endDay();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              state.streak = st.ok(state) ? state.streak + 1 : 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                updateDashboard();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (state.health <= 0) return failStage(true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (st.done(state)) return stageComplete();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (state.day >= st.maxDays) return failStage(false);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const done = state.day;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const word = dayWord();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            state.paused = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              playSound("chime");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                showOverlay(word + " " + done + " complete", dayComment(report), "", [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          label: "Start " + word.toLowerCase() + " " + (done + 1),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                note: "",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onClick: () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              hideOverlay();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      state.day++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              startDay();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // things worth knowing before the day ends
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function endDayWarnings() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const w = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (state.power >= 2) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  w.push("You still have " + state.power + " power left. It does not carry over to tomorrow.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const air = state.air - 12, food = state.food - 10, shield = state.shield - 8;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (air <= 40) w.push("Overnight your air will drop to about " + Math.max(0, air) + ". The goal needs it above 40.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (state.stage >= 1 && food <= 40) w.push("Overnight your food will drop to about " + Math.max(0, food) + ". The goal needs it above 40.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (shield <= 50) w.push("Overnight your shield will drop to about " + Math.max(0, shield) + ". The goal needs it above 50.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (state.health < 40) w.push("Crew health is low (" + state.health + ").");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return w;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // asks first if there is something the player may want to fix
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function requestEndDay() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (state.over || state.paused) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const warnings = endDayWarnings();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (warnings.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          finishDay();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  state.paused = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    playSound("alert");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      showOverlay("Before you end the day", warnings.join("\n\n"), "", [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          { label: "Keep playing", note: "Go back and use your power.", onClick: () => { hideOverlay(); state.paused = false; } },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              { label: "End day anyway", note: "", onClick: () => { hideOverlay(); state.paused = false; finishDay(); } }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function stageComplete() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const st = STAGES[state.stage];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (state.stage >= STAGES.length - 1) return missionComplete();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      state.paused = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        playSound("win");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const next = state.stage + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            showOverlay("Stage " + (state.stage + 1) + " complete!",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Well done! You met the goal: " + st.goal + "\n\n" + st.learn +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "\n\nA supply ship arrives with air, food and shield materials.", "", [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              label: "Go to Stage " + (next + 1),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    note: "New: " + st.unlocked,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onClick: () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  hideOverlay();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          startStage(next, true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  showMap(gameScene, startDay);   // shows the newly opened area
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function failStage(dead) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                state.paused = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  playSound("fail");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    showOverlay(dead ? "The crew needs a rescue" : "Out of time on this stage", explainFailure(dead), "", [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              label: "Try this stage again",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    note: "Earth sends a supply ship first.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onClick: () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  hideOverlay();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          state.stats.retries++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  startStage(state.stage, false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          startDay();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        { label: "Back to Stage 1", note: "", onClick: () => { clearProgress(); location.reload(); } }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function missionComplete() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            state.over = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              state.paused = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                playSound("win");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  showOverlay("Mission complete!",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "Your outposts work, on the Moon and on Mars! You balanced air, food, shielding and science with only a little power each day, " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "which is exactly what real mission planners do.", "", [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              { label: "Play again", note: "", onClick: () => location.reload() }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  document.getElementById("ov-extra").innerHTML = missionReportHtml();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    clearProgress();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("end-day").addEventListener("click", requestEndDay);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("map-btn").addEventListener("click", openMap);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("help").addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (state.paused || state.over) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        state.paused = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          showHelp();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          document.getElementById("sound-btn").addEventListener("click", toggleSound);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          updateSoundButton();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // bigger text option for the panels and popups
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          document.getElementById("text-btn").addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const big = document.body.classList.toggle("big-text");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              try { localStorage.setItem("outpostBigText", big ? "1" : "0"); } catch (e) { }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              try { if (localStorage.getItem("outpostBigText") === "1") document.body.classList.add("big-text"); } catch (e) { }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              new Phaser.Game({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                type: Phaser.AUTO,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  width: 960,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    height: 640,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      parent: "game-container",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        backgroundColor: "#777d91",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          physics: { default: "arcade", arcade: { debug: false } },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            scale: isSmallScreen
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ? { mode: Phaser.Scale.RESIZE }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    : { mode: Phaser.Scale.FIT, autoCenter: Phaser.Scale.CENTER_BOTH },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      scene: [OutpostScene]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });